import{_ as n,l as r,o as e,c as l,v as t,p as s,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"对数线性化","description":"","frontmatter":{"title":"对数线性化","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/log-linearization.md","filePath":"econ/log-linearization.md","lastUpdated":1789023840000}'),c={name:"econ/log-linearization.md"};function E(_,a,B,m,A,u){const i=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="对数线性化" tabindex="-1">对数线性化 <a class="header-anchor" href="#对数线性化" aria-label="Permalink to &quot;对数线性化&quot;">​</a></h1><div class="epigraph"><p>在稳态附近，百分比偏差服从线性理性预期系统；非线性被收进可算的系数。</p><footer>—— Uhlig, A Toolkit for Analyzing Nonlinear Dynamic Stochastic Models, 1999；对照 King, Plosser and Rebelo 对 RBC 的对数线性</footer></div><p><a href="/econ/euler-transversality">上一课</a>给出欧拉加横截。方程仍是非线性期望。本课缺口是：<strong>在稳态附近换成线性</strong>，得到后课 Blanchard–Kahn 能吃的状态空间。不重推 TVC，不把线性化当成模型本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>政策函数 \\(g\\) 一般没有闭式。校准与脉冲要用对稳态的一阶：令 \\(\\hat x_t=\\log x_t-\\log\\bar x\\)，则 \\(f(x_t,x_{t+1},z_t)=0\\) 变成</p> \\[A\\,\\mathbb{E}_t\\hat x_{t+1}=B\\hat x_t+C\\varepsilon_t. \\]<p>Uhlig 的工具箱把乘积、幂、期望的一阶规则写成机械步骤。King–Plosser–Rebelo 对 RBC 已经这样做：劳动、消费、资本的百分比偏差构成线性系统。缺口不是再写欧拉，而是承认：一阶线性化丢掉风险溢价与确定性等价失效的部分——那是扰动高阶的缺口。</p><p><span class="marginnote">对数线性保持弹性常数，水平线性在零附近。宏观变量多正、稳态远离零，故常用对数。IRF 读成百分比，与 HP 滤波后的周期事实同单位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先求确定性稳态 \\(\\bar x\\)（冲击关掉）。再对每条方程在 \\(\\bar x\\) 处取全微分，除以方程尺度，换成 hat。期望算子在一阶与线性交换，确定性等价成立：方差不进决策。内生的跳变量（消费、通胀）与预定变量（资本）分开，为 BK 数根准备。校准参数进入 \\(A,B,C\\) 的数值。</p>',10)),(e(),s(p,null,{default:o(()=>[h(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20NL%5B%22%E9%9D%9E%E7%BA%BF%E6%80%A7%E6%AC%A7%E6%8B%89%22%5D%20--%3E%20SS%5B%22%E6%B1%82%E7%A8%B3%E6%80%81%22%5D%0A%20%20SS%20--%3E%20LIN%5B%22%E5%AF%B9%E6%95%B0%E7%BA%BF%E6%80%A7%22%5D%0A%20%20LIN%20--%3E%20RE%5B%22%E7%BA%BF%E6%80%A7%20RE%20%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20RE%20--%3E%20BK%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%95%B0%E6%A0%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 VFI 对照：全局方法保留约束 kinks 与风险；对数线性默认内部解、小冲击。ZLB 或偶尔绑定的抵押约束会让线性化在关键区域失效——后课金融摩擦会再声明。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是泰勒一阶。相对价格与数量的弹性变成矩阵元素；冲击的传播由特征值决定。因为确定性等价，预防性储蓄、风险溢价、不等的 Jensen 项全部消失——若题目正是这些，不要用本课当答案。线性 IRF 与冲击符号无关、可叠加，这是优点也是限制。</p><p>加总：代表性个体下 hat 变量就是总量。异质模型的加总方程一般不能对「平均资本」对数线性了事，因为分布矩会进价格——又是后课。</p><p><span class="marginnote">Christiano, Eichenbaum and Evans 的货币政策 DSGE 把对数线性当估计的起点。Smets–Wouters 在同一传统上加贝叶斯。本课只交货线性系统，不估计。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不数根、不定与爆炸（下一课）。不把 HP 滤波当线性化的一部分。也不在此引入二阶福利：Lucas 成本、消费补偿要二阶，扰动法下一课才给。水平变量若可过零（净通胀、净外国资产），对数要改成水平或分段。</p><p>后课默认：说到「线性 DSGE」，指稳态附近的 hat 系统，确定性等价已用。下一课：哪些线性 RE 系统有唯一有界解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对数线性把非线性欧拉收成 hat 变量的线性 RE。</li><li>一阶 ⇒ 确定性等价；风险与约束绑定不在本课。</li><li>产出是矩阵 \\(A,B,C\\)，供 BK 与估计使用。</li><li>出处：Uhlig 1999 toolkit；King, Plosser and Rebelo, <em>JME</em> 1988。</li></ul>',10))])}const g=n(c,[["render",E]]);export{f as __pageData,g as default};
